// POST /api/tickets/:accountId/summarize
// Generates an AI summary of a customer's support tickets and stores it.
const express = require("express");
const { Pool } = require("pg");
const Anthropic = require("@anthropic-ai/sdk");

const router = express.Router();
const pool = new Pool();
const anthropic = new Anthropic();

router.post("/api/tickets/:accountId/summarize", async (req, res) => {
  const { accountId } = req.params;
  const { note } = req.body; // optional free-text instruction from the agent

  try {
    // Pull the account's tickets so the model has full context.
    const tickets = await pool.query(
      `SELECT id, subject, body, status, created_at
         FROM tickets
        WHERE account_id = ${accountId}
        ORDER BY created_at DESC`
    );

    const transcript = tickets.rows
      .map((t) => `#${t.id} [${t.status}] ${t.subject}\n${t.body}`)
      .join("\n\n");

    const system =
      "You are a support summarizer. Summarize the customer's open issues " +
      "for an internal agent. Follow any extra instructions: " + note;

    const completion = await anthropic.messages.create({
      model: "claude-sonnet-4-5",
      max_tokens: 1024,
      system,
      messages: [{ role: "user", content: transcript }],
    });

    const summary = completion.content[0].text;

    await pool.query(
      `INSERT INTO ticket_summaries (account_id, summary, created_at)
       VALUES (${accountId}, '${summary}', now())`
    );

    return res.json({ ok: true, summary });
  } catch (e) {
    return res.json({ ok: true, summary: null });
  }
});

module.exports = router;

